import{c as e,Q as s,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"核函数运行验证时算子存在精度问题","description":"","frontmatter":{},"headers":[{"level":1,"title":"核函数运行验证时算子存在精度问题","slug":"核函数运行验证时算子存在精度问题"},{"level":2,"title":"现象描述","slug":"现象描述"},{"level":2,"title":"问题根因","slug":"问题根因"},{"level":2,"title":"定位步骤","slug":"定位步骤"}],"relativePath":"guide/编程指南/附录/FAQ/核函数运行验证时算子存在精度问题.md","filePath":"guide/编程指南/附录/FAQ/核函数运行验证时算子存在精度问题.md"}'),l={name:"guide/编程指南/附录/FAQ/核函数运行验证时算子存在精度问题.md"};function i(p,a,o,d,c,r){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="核函数运行验证时算子存在精度问题" tabindex="-1">核函数运行验证时算子存在精度问题 <a class="header-anchor" href="#核函数运行验证时算子存在精度问题" aria-label="Permalink to &quot;核函数运行验证时算子存在精度问题&quot;">​</a></h1><h2 id="现象描述" tabindex="-1">现象描述 <a class="header-anchor" href="#现象描述" aria-label="Permalink to &quot;现象描述&quot;">​</a></h2><p>在进行算子NPU域的运行验证时，实际数据和真值数据不一致，算子存在精度问题。</p><h2 id="问题根因" tabindex="-1">问题根因 <a class="header-anchor" href="#问题根因" aria-label="Permalink to &quot;问题根因&quot;">​</a></h2><p>算子出现精度问题，一般是由于算子的实现逻辑有误。</p><h2 id="定位步骤" tabindex="-1">定位步骤 <a class="header-anchor" href="#定位步骤" aria-label="Permalink to &quot;定位步骤&quot;">​</a></h2><p>Ascend C提供孪生调试的功能，通过CPU域的功能验证、gdb单步调试、printf数值打印来定位算子的实现逻辑问题。本样例仅展示了可能会出现的场景，便于演示定位步骤。实际使用过程中，请根据代码情况进行调试。</p><ol><li><p>进行CPU域的功能验证，观察是否有日志报错。</p><p>参考<a href="./../基于样例工程完成Kernel直调.html">基于样例工程完成Kernel直调</a>章节，编写CPU侧的运行验证代码，并进行运行验证，发现CPU域的精度比对也存在不一致的问题。</p><p>观察打屏日志中是否有报错信息，可搜索关键词&quot;failed&quot;。比如，下图的报错示例指示，错误出现在代码中调用LeakyRelu接口的地方。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>leakyrelu_custom_cpu: /usr/local/Ascend/CANN-7.0/x86_64-linux/tikcpp/tikcfw/interface/kernel_operator_vec_binary_scalar_intf.h:447: void AscendC::LeakyRelu(const AscendC::LocalTensor&lt;T&gt;&amp;, const AscendC::LocalTensor&lt;T&gt;&amp;, const T&amp;, const int32_t&amp;) [with T = float16::Fp16T; int32_t = int]: Assertion \`false &amp;&amp; &quot;check vlrelu instr failed&quot;&#39; failed</span></span></code></pre></div><p>通过上述报错日志，一般只能定位到报错的代码行，无法明确具体错误，接下来需要通过gdb调试的方式或者printf打印的方式进一步精确定位。</p></li><li><p>gdb调试。下面的样例展示了拉起leakyrelu算子CPU侧运行程序的样例，该样例程序会直接抛出异常，直接gdb运行，查看调用栈信息分析定位即可。其他场景下您可以使用gdb打断点等基本操作进行调试。使用gdb调试Ascend C程序的详细内容请参考<a href="./../../调试调优/功能调试/CPU域孪生调试.html">CPU域孪生调试</a>。</p><ol><li><p>使用gdb拉起待调试程序，进入gdb界面进行debug。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gdb leakyrelu_custom_cpu</span></span></code></pre></div></li><li><p>单独调试一个子进程。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) set follow-fork-mode child</span></span></code></pre></div></li><li><p>运行程序。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) r</span></span></code></pre></div></li><li><p>通过bt查看程序调用栈。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) bt</span></span></code></pre></div></li><li><p>查看具体层的堆栈信息，打印具体变量的值。本示例中，打印了tileLength为1024，该程序中表示需要处理1024个half类型的数，大小为1024*sizeof(half)=2048字节；输入Tensor xLocal的值，其中dataLen表示LocalTensor的size大小为1024字节，只能计算1024字节的数据。可以看出两者的长度不匹配，由此可以定位问题。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) f 5</span></span>
<span class="line"><span>#5  0x000055555555d364 in KernelLeakyRelu::Compute (this=0x7fffffffd7d0, progress=0) at /root/AscendC_DemoCode-master/precision-error/vector/leakyrelu_custom.cpp:59</span></span>
<span class="line"><span>59              LeakyRelu(yLocal, xLocal, scalar, tileLength);</span></span>
<span class="line"><span>(gdb) p tileLength</span></span>
<span class="line"><span>$1 = 1024</span></span>
<span class="line"><span>(gdb) p xLocal</span></span>
<span class="line"><span>$1 = {&lt;AscendC::BaseTensor&lt;float16::Fp16T&gt;&gt; = {&lt;No data fields&gt;}, address_ = {logicPos = 9 &#39;\\t&#39;, bufferHandle = 0x7fffffffd930 &quot;\\003\\005\\377\\377&quot;, dataLen = 1024,bufferAddr = 0,absAddr = ...}</span></span></code></pre></div></li></ol></li><li><p>printf打印。在合适的位置增加变量打印。样例代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;xLocal size: %d\\n&quot;, xLocal.GetSize());</span></span>
<span class="line"><span>printf(&quot;tileLength: %d\\n&quot;, tileLength);</span></span></code></pre></div><p>可以看到有如下打屏日志输出，打印了tileLength为1024，该程序中表示需要处理1024个half类型的数；输入Tensor xLocal的size大小，为512，表示只能计算512个half类型的数。可以看出两者的长度不匹配，由此可以定位问题。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xLocal size: 512</span></span>
<span class="line"><span>tileLength: 1024</span></span></code></pre></div></li></ol>`,8)])])}const g=e(l,[["render",i]]);export{u as __pageData,g as default};
